content.query:
// One-row health banner. Always renders; green ✓ when data is reachable in
// the selected Workspace, amber ⚠ when nothing matches — so a fresh deploy
// with the wrong Workspace param or an empty table is obvious instead of
// silently rendering every panel blank.
print n = toscalar(LoadTestSummary_CL | summarize count())
| extend ['Data source'] = iif(n > 0, strcat('✓ Connected — ', tostring(n), ' record(s) in LoadTestSummary_CL'), '⚠ No data in LoadTestSummary_CL — check the Workspace parameter above, widen Time range, or run the pipeline first')
| project ['Data source']

parameters.query:
// Dropdown is scoped by the global Scenario filter so picking a scenario
// trims the sampler list to just that scenario's tasks. parse_status filter
// keeps metadata-only / regression-check rows out — they have empty
// scenario_name and would surface as an empty option.
LoadTestSummary_CL
| where '{Scenario}' == '*' or scenario == '{Scenario}'
| where isnotempty(scenario_name) and parse_status == 'ok' and coalesce(cold_start, false) == false
| distinct scenario_name
| order by scenario_name asc

content.query:
// Run-indexed x-axis (NOT time): each Run # is a discrete categorical
// position so runs are equally spaced regardless of how long elapsed
// between them. Time-based axis crammed bursts and isolated long-gap
// runs together making run-to-run trends unreadable. Chronological order
// is preserved via the upstream `order by TimeGenerated asc`.
//
// Pivoted into wide-form (one numeric column per Sampler) so Workbook's
// linechart treats each Sampler as its own series automatically. The
// long-form (Run, Sampler, value) shape causes Workbook to collapse
// samplers via Sum at each x-axis position.
//
// Metric translation inlined as a case() because KQL `column_ifexists`
// requires a string literal — a let-bound variable doesn't compile.
LoadTestSummary_CL
| where TimeGenerated {TimeRange}
| where '{Scenario}' == '*' or scenario == '{Scenario}'
| where '{Version}' == '*' or umbraco_version == '{Version}'
| where '{Tier}' == '*' or infra_tier == '{Tier}'
| where '*' in ({Sampler}) or scenario_name in ({Sampler})
| where isnotempty(scenario_name) and parse_status == 'ok' and coalesce(cold_start, false) == false
| extend value = case(
    '{Metric}' == 'p95 (ms)',              toreal(p95_ms),
    '{Metric}' == 'p99 (ms)',              toreal(p99_ms),
    '{Metric}' == 'avg (ms)',              toreal(avg_ms),
    '{Metric}' == 'error rate',            toreal(error_rate),
    '{Metric}' == 'Requests/sec',          toreal(requests_per_sec),
    '{Metric}' == 'Server CPU peak %',     toreal(plan_CpuPercentage_max),
    '{Metric}' == 'Database load peak %',  toreal(sql_dtu_consumption_percent_max),
    real(null))
| where isnotnull(value)
| extend Sampler = strcat(scenario_name, ' | ', umbraco_version, ' | ', infra_tier)
| extend Run = strcat(format_datetime(TimeGenerated, 'yyyy-MM-dd HH:mm'), ' #', run_id)
| project Run, Sampler, value
| evaluate pivot(Sampler, any(value))
| order by Run asc

// Server-side resource pressure per run. Read alongside the latency chart
// to the LEFT: if latency climbs as Server CPU / Database load does, you're
// infra-bound; if they diverge, the regression is code-side. Run-indexed
// x-axis matches the chart on the left and prevents Workbook's time-bin
// aggregation from summing peak-percentages across rows (a 'Sum' line
// showing 300%+ is meaningless).
//
// Unpivoted to long-form so the chart can render one line per
// (metric × tier). Otherwise a multi-tier sweep zigzags between the
// tiers' values on a single 'Server CPU' line.
// Resource metrics are duplicated across all per-sampler rows of the
// same run by the publish script, so arg_max by run_id returns valid
// run-level values — picking any sampler row is fine.
let pressure = LoadTestSummary_CL
    | where TimeGenerated {TimeRange}
    | where '{Scenario}' == '*' or scenario == '{Scenario}'
    | where '{Version}' == '*' or umbraco_version == '{Version}'
    | where '{Tier}' == '*' or infra_tier == '{Tier}'
    | where parse_status == 'ok' and coalesce(cold_start, false) == false
    | summarize arg_max(TimeGenerated, *) by run_id, umbraco_version, infra_tier;
union
    (pressure | extend metric='Server CPU peak %',    value=round(todouble(plan_CpuPercentage_max), 1)),
    (pressure | extend metric='Server memory peak %', value=round(todouble(plan_MemoryPercentage_max), 1)),
    (pressure | extend metric='Database load peak %', value=round(todouble(sql_dtu_consumption_percent_max), 1)),
    (pressure | extend metric='Database CPU peak %',  value=round(todouble(sql_cpu_percent_max), 1))
| where isnotnull(value)
| extend Run = strcat(format_datetime(TimeGenerated, 'yyyy-MM-dd HH:mm'), ' #', run_id), Series = strcat(metric, ' | ', infra_tier)
| project Run, Series, value
| evaluate pivot(Series, any(value))
| order by Run asc

parameters.query:
// Inherits the global Scenario filter when set: with a global selection the
// dropdown lists only that scenario and showDefault auto-picks it; with `*` it
// shows the full universe. parse_status filter keeps metadata-only rows from
// surfacing scenarios that never produced metrics — otherwise picking them
// would render an empty Tiers chart.
LoadTestSummary_CL
| where '{Scenario}' == '*' or scenario == '{Scenario}'
| where isnotempty(scenario_name) and parse_status == 'ok' and coalesce(cold_start, false) == false
| distinct scenario
| where isnotempty(scenario)
| order by scenario asc

content.query:
// Per-sampler detail aggregated across runs. Run-level resource metrics
// (Server CPU peak, Database load peak) are NOT shown here — they're
// identical for every sampler in the same run, so they'd just repeat the
// same number on every row. Those values live in the Capacity verdict
// table above. median + p95 spread (stdev) give the typical reading and
// how much the runs disagree; worst Error % surfaces a single bad run that
// the median would otherwise hide.
LoadTestSummary_CL
| where scenario == '{TiersScenario}' and umbraco_version == '{TiersVersion}'
| where isnotempty(scenario_name) and parse_status == 'ok' and coalesce(cold_start, false) == false
| summarize
    Runs                  = count(),
    Requests              = toint(percentile(request_count, 50)),
    ['Requests/sec']      = round(percentile(todouble(requests_per_sec), 50), 1),
    ['avg (ms)']          = round(percentile(avg_ms, 50), 0),
    ['p95 (ms)']          = round(percentile(p95_ms, 50), 0),
    ['p95 spread (ms)']   = round(stdev(p95_ms), 0),
    ['p99 (ms)']          = round(percentile(p99_ms, 50), 0),
    ['max (ms)']          = round(max(max_ms), 0),
    ['median Error %']    = round(percentile(error_rate, 50) * 100, 2),
    ['worst Error %']     = round(max(error_rate) * 100, 2)
    by Sampler = scenario_name, Tier = infra_tier
| order by Sampler asc, Tier asc

parameters.query:
// One row per (run_id × scenario × version × tier) so a pipeline run that
// swept multiple cases gets one dropdown entry per case — picking the wrong
// one would otherwise mix cases via scenario_name joins. value is a composite
// 'run_id|scenario|version|tier' the comparison queries split on.
// Baseline default = second-most-recent (the comparison reference); the
// most-recent run is hidden so showDefault picks the previous one, giving
// 'previous vs newest' as the default comparison instead of 'newest vs
// newest' which would render an identity-delta table.
// parse_status filter excludes failed runs (no_metrics, no_results_dir) - they
// have a metadata-only row but no sampler data, so picking one as baseline or
// candidate yields an empty comparison.
let pool = LoadTestSummary_CL
    | where TimeGenerated {TimeRange}
    | where parse_status == 'ok'
    | where isnotempty(scenario) and isnotempty(umbraco_version) and isnotempty(infra_tier)
    | summarize arg_max(TimeGenerated, *) by run_id, scenario, umbraco_version, infra_tier;
let newest_ts = toscalar(pool | summarize max(TimeGenerated));
pool
| where TimeGenerated < newest_ts
| project value = strcat(run_id, '|', scenario, '|', umbraco_version, '|', infra_tier),
          label = strcat(format_datetime(TimeGenerated, 'yyyy-MM-dd HH:mm'), ' · ', scenario, ' / ', umbraco_version, ' / ', infra_tier, ' (#', run_id, ')'),
          TimeGenerated
| order by TimeGenerated desc
| project value, label

// Candidate is the run under test. Default = most recent, so 'previous vs
// newest' is the out-of-the-box comparison (Baseline excludes the most
// recent for exactly this reason). parse_status filter mirrors the Baseline
// dropdown - failed runs aren't comparable.
LoadTestSummary_CL
| where TimeGenerated {TimeRange}
| where parse_status == 'ok'
| where isnotempty(scenario) and isnotempty(umbraco_version) and isnotempty(infra_tier)
| summarize arg_max(TimeGenerated, *) by run_id, scenario, umbraco_version, infra_tier
| project value = strcat(run_id, '|', scenario, '|', umbraco_version, '|', infra_tier),
          label = strcat(format_datetime(TimeGenerated, 'yyyy-MM-dd HH:mm'), ' · ', scenario, ' / ', umbraco_version, ' / ', infra_tier, ' (#', run_id, ')'),
          TimeGenerated
| order by TimeGenerated desc
| project value, label

content.query:
// Header rows showing exactly which case is on each side, so the reviewer
// can confirm they're comparing like-for-like. Commit comes from the per-
// run summary row. The 'Diff' column is populated only when RepoCompareUrl
// is set, producing a clickable baseline..candidate URL.
let b_parts = split('{Baseline}', '|');
let c_parts = split('{Candidate}', '|');
let b_commit = toscalar(LoadTestSummary_CL
    | where run_id == tostring(b_parts[0]) and scenario == tostring(b_parts[1]) and umbraco_version == tostring(b_parts[2]) and infra_tier == tostring(b_parts[3])
    | extend safe_commit = tostring(column_ifexists("commit", ""))
    | summarize arg_max(TimeGenerated, safe_commit)
    | project safe_commit);
let c_commit = toscalar(LoadTestSummary_CL
    | where run_id == tostring(c_parts[0]) and scenario == tostring(c_parts[1]) and umbraco_version == tostring(c_parts[2]) and infra_tier == tostring(c_parts[3])
    | extend safe_commit = tostring(column_ifexists("commit", ""))
    | summarize arg_max(TimeGenerated, safe_commit)
    | project safe_commit);
let diff_url = iif(strlen('{RepoCompareUrl}') > 0 and strlen(b_commit) > 0 and strlen(c_commit) > 0, strcat('{RepoCompareUrl}', substring(b_commit, 0, 8), '...', substring(c_commit, 0, 8)), '');
print Side = 'Baseline',  ['Run #'] = tostring(b_parts[0]), Scenario = tostring(b_parts[1]), Version = tostring(b_parts[2]), Tier = tostring(b_parts[3]), Commit = substring(b_commit, 0, 8), Diff = ''
| union (print Side = 'Candidate', ['Run #'] = tostring(c_parts[0]), Scenario = tostring(c_parts[1]), Version = tostring(c_parts[2]), Tier = tostring(c_parts[3]), Commit = substring(c_commit, 0, 8), Diff = diff_url)

// {Baseline}/{Candidate} values are composite keys 'run_id|scenario|version|tier'
// produced by the dropdown queries above. Split here so a single dropdown
// pick targets exactly one case of one run, not 'all cases of run_id'.
let b_parts = split('{Baseline}', '|');
let c_parts = split('{Candidate}', '|');
let baseline = LoadTestSummary_CL
    | where run_id == tostring(b_parts[0]) and scenario == tostring(b_parts[1]) and umbraco_version == tostring(b_parts[2]) and infra_tier == tostring(b_parts[3])
    | where isnotempty(scenario_name);
let candidate = LoadTestSummary_CL
    | where run_id == tostring(c_parts[0]) and scenario == tostring(c_parts[1]) and umbraco_version == tostring(c_parts[2]) and infra_tier == tostring(c_parts[3])
    | where isnotempty(scenario_name);
let delta = (a:real, b:real) { iif(a == 0 or isnull(a) or isnull(b), real(null), round((b - a) / a * 100.0, 0)) };
baseline
| join kind=fullouter (candidate) on scenario_name
// Columns grouped per metric (raw baseline, raw candidate, change %) so each
// row reads as 'for this sampler: avg story, p95 story, p99 story' instead
// of jumping between far-apart raw and % blocks.
| project Sampler = coalesce(scenario_name, scenario_name1),
          ['Reqs baseline'] = request_count,    ['Reqs candidate'] = request_count1,
          ['avg baseline (ms)'] = round(avg_ms, 0), ['avg candidate (ms)'] = round(avg_ms1, 0), ['avg change %'] = delta(avg_ms, avg_ms1),
          ['p95 baseline (ms)'] = round(p95_ms, 0), ['p95 candidate (ms)'] = round(p95_ms1, 0), ['p95 change %'] = delta(p95_ms, p95_ms1),
          ['p99 baseline (ms)'] = round(p99_ms, 0), ['p99 candidate (ms)'] = round(p99_ms1, 0), ['p99 change %'] = delta(p99_ms, p99_ms1)
| order by Sampler asc

// Long-form output (Sampler, Series, p95 ms) instead of pivoting Series
// into columns. Workbook bar charts render pivoted multi-numeric columns
// as stacked by default; long-form with a categorical Series column
// renders side-by-side bars reliably.
let b_parts = split('{Baseline}', '|');
let c_parts = split('{Candidate}', '|');
let baseline = LoadTestSummary_CL
    | where run_id == tostring(b_parts[0]) and scenario == tostring(b_parts[1]) and umbraco_version == tostring(b_parts[2]) and infra_tier == tostring(b_parts[3])
    | where isnotempty(scenario_name);
let candidate = LoadTestSummary_CL
    | where run_id == tostring(c_parts[0]) and scenario == tostring(c_parts[1]) and umbraco_version == tostring(c_parts[2]) and infra_tier == tostring(c_parts[3])
    | where isnotempty(scenario_name);
union
    (baseline  | project Sampler = scenario_name, Series = 'Baseline',  ['p95 (ms)'] = todouble(p95_ms)),
    (candidate | project Sampler = scenario_name, Series = 'Candidate', ['p95 (ms)'] = todouble(p95_ms))
| where isnotnull(['p95 (ms)'])
| order by Sampler asc, Series asc

parameters.query:
// Dropdown sourced from the same runs the table above shows, in the same
// time range and global filter scope. value = run_id (string) so the drill
// queries below can compare directly; label adds context so the right run
// is easy to spot. Includes failed runs so the per-sampler detail panel
// can still surface 'no rows' clearly for them.
LoadTestSummary_CL
| where TimeGenerated {TimeRange}
| where '{Scenario}' == '*' or scenario == '{Scenario}'
| where '{Version}' == '*' or umbraco_version == '{Version}'
| where '{Tier}' == '*' or infra_tier == '{Tier}'
| where parse_status in ('ok', 'no_metrics', 'no_results_dir')
| summarize arg_max(TimeGenerated, scenario, umbraco_version, infra_tier) by run_id
| project value = tostring(run_id),
          label = strcat(format_datetime(TimeGenerated, 'yyyy-MM-dd HH:mm'), ' #', run_id, ' · ', scenario, ' / ', umbraco_version, ' / ', infra_tier),
          TimeGenerated
| order by TimeGenerated desc
| project value, label

content.query:
// Regression detail for the drilled run — which specific samplers regressed
// per case, sourced from the regression_check rows posted by scripts/check-
// regression.ps1. Empty result = no regression row exists for this run
// (regression stage skipped, hasn't completed, or this run predates the
// regression-LA integration).
LoadTestSummary_CL
| where run_id == '{DrillRun}' and parse_status == 'regression_check'
| project Scenario=scenario, Version=umbraco_version, Tier=infra_tier,
          Verdict=case(
              regression_status == 'regress',      'regression detected',
              regression_status == 'pass',         'no regression',
              regression_status == 'insufficient', 'not enough history',
              regression_status),
          ['Regressed samplers']=replace_string(coalesce(regressed_samplers, ''), ',', ', '),
          ['# regressed']=coalesce(regressed_count, 0)
| order by Verdict asc, Scenario asc, Version asc, Tier asc

// Drill-down: paste a run_id into the parameter to see per-sampler detail for
// that run. Tier column is required because a multi-tier pipeline run produces
// one row per (sampler, tier) — without Tier the table shows duplicate sampler
// names with no way to tell Standard from Starter.
LoadTestSummary_CL
| where run_id == '{DrillRun}' and isnotempty(scenario_name)
| project Tier=infra_tier, Sampler=scenario_name,
          Reqs=request_count, Fails=failure_count,
          ['Error %']=round(error_rate*100, 1),
          Avg=round(avg_ms, 0), p50=round(p50_ms, 0), p90=round(p90_ms, 0), p95=round(p95_ms, 0), p99=round(p99_ms, 0), Max=round(max_ms, 0)
| order by Sampler asc, Tier asc

// Per-minute resource pressure (% metrics only) for the drilled run.
// Sourced from LoadTestSeries_CL. Split from the HTTP-error chart below
// because percentages share a 0-100 scale where errors would visually flatten.
LoadTestSeries_CL
| where run_id == '{DrillRun}'
| where metric_name !startswith 'app_Http'
| project TimeGenerated, metric_name, value
| evaluate pivot(metric_name, any(value))
| order by TimeGenerated asc

// Per-minute HTTP error counts (4xx / 5xx) for the drilled run. Separate
// chart from the % metrics above so the count Y-axis auto-scales to the
// natural range (usually 0-10 except during spikes) instead of being crushed
// against a 0-100 floor shared with CPU/DTU percentages.
LoadTestSeries_CL
| where run_id == '{DrillRun}'
| where metric_name startswith 'app_Http'
| project TimeGenerated, metric_name, value
| evaluate pivot(metric_name, any(value))
| order by TimeGenerated asc

// Long-form (Version, Tier, total_ms) + `group: Tier` so bars render
// side-by-side per version — compare tiers within each version. Avg
// end-to-end time-to-first-edit across all matching runs.
ClientMeasurement_CL
| where metric == "time_to_first_edit"
| summarize ['total_ms'] = round(avg(median_ms), 0) by Version = umbraco_version, Tier = infra_tier
| order by Version asc, Tier asc
